properties.property:

{
  "settings": {
    "number_of_shards": 1,
    "number_of_replicas": 0,
    "analysis": {
      "filter": {
        "cn_stop": {
          "type": "stop",
          "stopwords": ["的", "了", "是", "在", "和", "或", "与", "对", "中", "也", "都", "就", "而"]
        }
      },
      "analyzer": {
        "cn_index_analyzer": {
          "type": "custom",
          "tokenizer": "ik_max_word",
          "filter": ["lowercase", "cn_stop"]
        },
        "cn_search_analyzer": {
          "type": "custom",
          "tokenizer": "ik_smart",
          "filter": ["lowercase", "cn_stop"]
        }
      }
    }
  },
  "mappings": {
    "properties": {
      "chunk_id":    { "type": "keyword" },
      "document_id": { "type": "keyword" },
      "batch_id":    { "type": "keyword" },
      "is_active":   { "type": "boolean" },
      "doc_path":    { "type": "keyword" },
      "anchor":      { "type": "keyword" },
      "domain":      { "type": "keyword" },
      "doc_type":    { "type": "keyword" },
      "heading_path": {
        "type": "text",
        "analyzer": "cn_index_analyzer",
        "search_analyzer": "cn_search_analyzer",
        "fields": {
          "keyword": { "type": "keyword" }
        }
      },
      "content": {
        "type": "text",
        "analyzer": "cn_index_analyzer",
        "search_analyzer": "cn_search_analyzer",
        "fields": {
          "en": {
            "type": "text",
            "analyzer": "english"
          }
        }
      },
      "embedding": {
        "type": "dense_vector",
        "dims": 1024,
        "index": true,
        "similarity": "cosine"
      },
      "created_at": { "type": "date" }
    }
  }
}
